/**
 * Handles attachment failures before payload transformation.
 *
 * Reads entry.metadata.failed_files — set by the prune node and accumulated
 * by Classify attachments and Fetch WaSOS files on the GET side.
 *
 * For WaSOS destinations all failures are known now (no upload step follows).
 * Patches entry.text with a receiver notice showing the correct count,
 * and fires a sender notification via link-call.
 *
 * For Rayvn destinations both are deferred until after upload in
 * POST to Rayvn log — upload failures are not yet known.
 *
 * Output 1: msg continues (always)
 * Output 2: notification payload for WaSOS destinations (null otherwise)
 */
const entry  = msg.entry;
const failed = entry.metadata.failed_files || [];

// No failures — nothing to do regardless of destination
if (failed.length === 0) return [msg, null];

// Rayvn: defer until after upload where the complete failure picture is known
if (entry.metadata.target.client_system === "rayvn") return [msg, null];

// WaSOS (and any future non-upload systems): all failures known now
const succeeded = entry.files.length;
const total     = succeeded + failed.length;
const notice    = " [" + failed.length + "/" + total
                + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";

// Append notice to entry.text — Bridge to WaSOS uses entry.text as content
entry.text = (entry.text || "") + notice;

const notification = {
    payload: {
        entry_id:     entry.id,
        failed_files: failed,
        entry_author: entry.author,
        metadata:     entry.metadata
    }
};

return [msg, notification];

/**
 * Adapts a bridge entry to the WaSOS message format.
 *
 * Sets msg.metadata = entry.metadata — the two are the same object from here on.
 * WaSOS does not support attachments via API, so files is always empty.
 * entry.text has already been patched by Handle failed files if needed.
 */
const entry  = msg.entry;
const source = entry.metadata.source;
const utils  = global.get("utils");

msg.metadata = entry.metadata;
msg.payload  = {
    content:        entry.text,
    callsign:       `${utils.build_callsign(source)} ${entry.author}`,
    isLocation:     false,
    replyMessageId: null,
    files:          []
};

return msg;

/**
 * Adapts a bridge entry to the Rayvn log entry format.
 *
 * Sets msg.metadata = entry.metadata — the two are the same object from here on.
 * Upload files to Rayvn writes upload failures directly to msg.metadata.failed_files,
 * which is also reflected in entry.metadata (same reference).
 *
 * entry.files is passed along — the upload node replaces these with Rayvn file IDs.
 * entry.text is not patched here; that is done by Patch receiver text after upload
 * when the complete failure picture is known.
 */
const entry  = msg.entry;
const source = entry.metadata.source;
const utils  = global.get("utils");

msg.metadata = entry.metadata;
msg.payload  = {
    text:             `${utils.build_callsign(source)} ${entry.author}: ${entry.text || ""}`,
    keyEvent:         false,
    releasedInfo:     false,
    loggedByFullName: `${utils.build_callsign(source)} ${entry.author}`,
    labels:           [],
    files:            entry.files || []
};

return msg;
